from math import comb
U=[0,0,1,3,5,8,12,16,21,27,33,36,40,45,50,55,60,68]
mins={17:68,16:60,15:50,14:41}
thresholds=[mins[18-s]+s*(10-s) for s in [1,2,3]]
assert thresholds==[77,76,71]
def Ds(q,s):
    h=18-s
    terms=[0,6-q,85-q-U[h]-min(8,h)*(s-1)-(s-1)**2//3]
    if s==4: terms.append(9-q)
    return max(terms)
def beta(s):
    a,b=divmod(s,4)
    return (4-b)*comb(a,2)+b*comb(a+1,2)
for q in range(36):
    for s,c in [(1,17),(2,17),(3,13),(4,9)]:
        assert Ds(q,s)==max(0,c-q)
for q,s,t,result in [(0,4,8,4),(4,3,8,3),(8,2,8,2),(9,1,7,1)]:
    cost=max(0,s*max(0,Ds(q,s)-t),85-q-U[18-s]+beta(s)-s*t)
    assert cost==result
assert [comb(h,2)-mins[h] for h in [17,16,15]]==[68,60,55]
print({'status':'PASS','thresholds':thresholds,'member_formula_checks':144,'conditional_excess_examples':4,'boundary_complement_checks':3})

from itertools import combinations
residues={1,2,4,8,9,13,15,16}
core=list(range(1,17))
edge={frozenset((i,j)) for i,j in combinations(core,2) if (i-j)%17 in residues}
edge|={frozenset((1,17)),frozenset((17,18))}
V=list(range(1,19))
def adj(i,j): return frozenset((i,j)) in edge
assert len(edge)==62
assert not any(all(adj(i,j) for i,j in combinations(S,2)) for S in combinations(V,4))
assert not any(all(not adj(i,j) for i,j in combinations(S,2)) for S in combinations(V,5))
deg={i:sum(adj(i,j) for j in V if i!=j) for i in V}
assert min(deg.values())==1
seen={1}
while True:
    more=seen|{j for i in seen for j in V if i!=j and adj(i,j)}
    if more==seen: break
    seen=more
assert len(seen)==18
print({'fixed_graph':'Paley17 minus0 plus pendant path of length2','n':18,'edges':62,'connected':True,'minimum_degree':1,'K4_checks':3060,'I5_checks':8568,'status':'PASS','scope':'isolated A, not an ambient order43 witness'})
